mapper.select:
SELECT idi.*,id.full_name
FROM `idevelop_device_inventory` idi
LEFT JOIN idevelop_dept id on idi.crop_id = id.id
where idi.is_deleted = 0

    and idi.region_code like concat(#{inventory.regionCode},'%')


    and idi.crop_id = #{inventory.cropId}


    and idi.warehouse_name like concat('%',#{inventory.warehouseName},'%')


    and idi.device_category = #{inventory.deviceCategory}


    and idi.device_type = #{inventory.deviceType}

limit #{sizeIndex},#{size}

SELECT count(*)
FROM `idevelop_device_inventory` idi
LEFT JOIN idevelop_dept id on idi.crop_id = id.id
where idi.is_deleted = 0

    and idi.region_code like concat(#{inventory.regionCode},'%')


    and idi.crop_id = #{inventory.cropId}


    and idi.warehouse_name like concat('%',#{inventory.warehouseName},'%')


    and idi.device_category = #{inventory.deviceCategory}


    and idi.device_type = #{inventory.deviceType}
